import { useCallback, useId, useState } from 'react';
import { JxButton, JxTagInput } from '@jinx-ui/react';

export interface ArticleTagPickerProps {
  defaultTags?: string[];
  onChange?: (tags: string[]) => void;
  label?: string;
  placeholder?: string;
  maxTags?: number;
}

export default function ArticleTagPicker({
  defaultTags = [],
  onChange,
  label = 'Теги статьи',
  placeholder = 'Введите тег и нажмите Enter',
  maxTags = 10,
}: ArticleTagPickerProps) {
  const listId = useId();

  const normalize = useCallback(
    (input: string[]): string[] => {
      const seen = new Set<string>();
      const result: string[] = [];
      for (const raw of input) {
        const tag = raw.trim().replace(/\s+/g, ' ');
        const key = tag.toLocaleLowerCase();
        if (!tag || seen.has(key)) continue;
        seen.add(key);
        result.push(tag);
        if (result.length >= maxTags) break;
      }
      return result;
    },
    [maxTags],
  );

  const [tags, setTags] = useState<string[]>(() => normalize(defaultTags));

  const commit = useCallback(
    (next: string[]) => {
      setTags(next);
      onChange?.(next);
    },
    [onChange],
  );

  const handleValueChange = useCallback(
    (next: string[]) => {
      commit(normalize(next));
    },
    [commit, normalize],
  );

  const removeTag = useCallback(
    (tag: string) => {
      commit(tags.filter((item) => item !== tag));
    },
    [commit, tags],
  );

  return (
    <div
      style={{
        display: 'flex',
        flexDirection: 'column',
        gap: 'var(--jx-space-2)',
      }}
    >
      <JxTagInput
        label={label}
        placeholder={placeholder}
        value={tags}
        onValueChange={handleValueChange}
        disabled={tags.length >= maxTags}
        aria-describedby={listId}
      />

      <div
        id={listId}
        role="list"
        aria-label="Выбранные теги"
        style={{
          display: 'flex',
          flexWrap: 'wrap',
          gap: 'var(--jx-space-2)',
          minHeight: 'var(--jx-space-6)',
        }}
      >
        {tags.map((tag) => (
          <span key={tag} role="listitem">
            <JxButton
              type="button"
              variant="ghost"
              size="sm"
              onClick={() => removeTag(tag)}
              aria-label={`Удалить тег ${tag}`}
            >
              {tag} ×
            </JxButton>
          </span>
        ))}
      </div>
    </div>
  );
}

